INSERT INTO muscle_groups (id, name, description) VALUES
    ('11111111-0000-0000-0000-000000000001', 'Chest',       'Pectoral muscles — upper, middle, and lower chest'),
    ('11111111-0000-0000-0000-000000000002', 'Back',        'Latissimus dorsi, rhomboids, and trapezius'),
    ('11111111-0000-0000-0000-000000000003', 'Shoulders',   'Anterior, lateral, and posterior deltoids'),
    ('11111111-0000-0000-0000-000000000004', 'Biceps',      'Biceps brachii and brachialis'),
    ('11111111-0000-0000-0000-000000000005', 'Triceps',     'Triceps brachii — long, lateral, and medial heads'),
    ('11111111-0000-0000-0000-000000000006', 'Quadriceps',  'Rectus femoris, vastus lateralis, medialis, and intermedius'),
    ('11111111-0000-0000-0000-000000000007', 'Hamstrings',  'Biceps femoris, semitendinosus, and semimembranosus'),
    ('11111111-0000-0000-0000-000000000008', 'Glutes',      'Gluteus maximus, medius, and minimus'),
    ('11111111-0000-0000-0000-000000000009', 'Core',        'Rectus abdominis, obliques, and transverse abdominis'),
    ('11111111-0000-0000-0000-000000000010', 'Cardio',      'Cardiovascular and full-body conditioning exercises');
INSERT INTO exercises (id, name, description, muscle_group_id, instructions) VALUES
    ('22222222-0000-0000-0000-000000000001', 'Barbell Bench Press',  'Classic compound chest exercise using a barbell.',            '11111111-0000-0000-0000-000000000001', E'1. Lie flat on a bench.\n2. Grip the barbell slightly wider than shoulder-width.\n3. Lower the bar to mid-chest.\n4. Press back to full extension.'),
    ('22222222-0000-0000-0000-000000000002', 'Dumbbell Bench Press', 'Dumbbell variation for greater range of motion.',             '11111111-0000-0000-0000-000000000001', E'1. Lie flat on a bench with a dumbbell in each hand.\n2. Lower dumbbells to chest level.\n3. Press upward until arms are extended.'),
    ('22222222-0000-0000-0000-000000000003', 'Push-Up',              'Bodyweight chest exercise requiring no equipment.',           '11111111-0000-0000-0000-000000000001', E'1. Start in a high plank position.\n2. Lower your chest to the floor.\n3. Push back up to starting position.'),
    ('22222222-0000-0000-0000-000000000004', 'Incline Dumbbell Press','Upper chest focused dumbbell press on an incline bench.',    '11111111-0000-0000-0000-000000000001', E'1. Set bench to 30-45 degree incline.\n2. Press dumbbells from shoulder level upward.\n3. Lower under control.'),
    ('22222222-0000-0000-0000-000000000005', 'Pull-Up',              'Bodyweight vertical pulling movement for the back.',          '11111111-0000-0000-0000-000000000002', E'1. Hang from a bar with overhand grip.\n2. Pull until chin clears the bar.\n3. Lower back to dead hang.'),
    ('22222222-0000-0000-0000-000000000006', 'Barbell Deadlift',     'Fundamental compound hinge movement.',                        '11111111-0000-0000-0000-000000000002', E'1. Stand with bar over mid-foot.\n2. Hinge at hips, grip the bar.\n3. Drive through the floor.\n4. Lower bar under control.'),
    ('22222222-0000-0000-0000-000000000007', 'Seated Cable Row',     'Horizontal pulling exercise targeting mid-back.',             '11111111-0000-0000-0000-000000000002', E'1. Sit at cable row machine, feet on platform.\n2. Pull handle to lower abdomen.\n3. Squeeze shoulder blades.\n4. Return to start.'),
    ('22222222-0000-0000-0000-000000000008', 'Lat Pulldown',         'Vertical pulling movement to develop lat width.',             '11111111-0000-0000-0000-000000000002', E'1. Grip the bar wider than shoulder-width.\n2. Pull the bar to upper chest.\n3. Slowly return to start.'),
    ('22222222-0000-0000-0000-000000000009', 'Overhead Press',       'Compound shoulder press with a barbell.',                     '11111111-0000-0000-0000-000000000003', E'1. Hold barbell at shoulder height.\n2. Press directly overhead.\n3. Lower under control.'),
    ('22222222-0000-0000-0000-000000000010', 'Dumbbell Lateral Raise','Isolation exercise for the lateral deltoid.',                '11111111-0000-0000-0000-000000000003', E'1. Stand with dumbbells at sides.\n2. Raise arms to shoulder height laterally.\n3. Lower slowly.'),
    ('22222222-0000-0000-0000-000000000011', 'Barbell Curl',         'Classic barbell bicep curl.',                                 '11111111-0000-0000-0000-000000000004', E'1. Stand with barbell in supinated grip.\n2. Curl the bar to shoulder height.\n3. Lower with control.'),
    ('22222222-0000-0000-0000-000000000012', 'Dumbbell Hammer Curl', 'Neutral-grip curl targeting brachialis and biceps.',          '11111111-0000-0000-0000-000000000004', E'1. Hold dumbbells with neutral grip.\n2. Curl to shoulder height.\n3. Lower slowly.'),
    ('22222222-0000-0000-0000-000000000013', 'Tricep Dips',          'Bodyweight tricep exercise on parallel bars or bench.',       '11111111-0000-0000-0000-000000000005', E'1. Support yourself on parallel bars.\n2. Lower until elbows are at 90 degrees.\n3. Press back up.'),
    ('22222222-0000-0000-0000-000000000014', 'Tricep Pushdown',      'Cable isolation exercise for the tricep.',                    '11111111-0000-0000-0000-000000000005', E'1. Stand at cable machine.\n2. Push downward until elbows fully extended.\n3. Return slowly.'),
    ('22222222-0000-0000-0000-000000000015', 'Barbell Back Squat',   'Foundational lower body compound movement.',                  '11111111-0000-0000-0000-000000000006', E'1. Bar on upper traps, feet shoulder-width.\n2. Squat until thighs parallel to floor.\n3. Drive through heels to stand.'),
    ('22222222-0000-0000-0000-000000000016', 'Leg Press',            'Machine-based quad-dominant lower body exercise.',            '11111111-0000-0000-0000-000000000006', E'1. Sit in leg press machine.\n2. Lower platform until knees at 90 degrees.\n3. Press back to full extension.'),
    ('22222222-0000-0000-0000-000000000017', 'Lunges',               'Unilateral lower body exercise targeting quads and glutes.',  '11111111-0000-0000-0000-000000000006', E'1. Step forward with one leg.\n2. Lower back knee toward the floor.\n3. Push off front foot to return.'),
    ('22222222-0000-0000-0000-000000000018', 'Romanian Deadlift',    'Hip hinge movement targeting hamstrings.',                    '11111111-0000-0000-0000-000000000007', E'1. Hold barbell with overhand grip.\n2. Hinge at hips, lower bar along legs.\n3. Drive hips forward to return.'),
    ('22222222-0000-0000-0000-000000000019', 'Lying Leg Curl',       'Isolation exercise for the hamstrings.',                      '11111111-0000-0000-0000-000000000007', E'1. Lie face-down on leg curl machine.\n2. Curl heels toward glutes.\n3. Lower slowly.'),
    ('22222222-0000-0000-0000-000000000020', 'Hip Thrust',           'Glute-dominant barbell hip extension.',                       '11111111-0000-0000-0000-000000000008', E'1. Sit with upper back on bench, barbell across hips.\n2. Drive hips upward until fully extended.\n3. Lower under control.'),
    ('22222222-0000-0000-0000-000000000021', 'Glute Bridge',         'Bodyweight glute activation exercise.',                       '11111111-0000-0000-0000-000000000008', E'1. Lie on back with knees bent.\n2. Drive hips upward, squeezing glutes at top.\n3. Lower slowly.'),
    ('22222222-0000-0000-0000-000000000022', 'Plank',                'Isometric core stabilisation exercise.',                      '11111111-0000-0000-0000-000000000009', E'1. Hold a forearm plank position.\n2. Keep hips level and core braced.\n3. Hold for target duration.'),
    ('22222222-0000-0000-0000-000000000023', 'Crunch',               'Basic abdominal flexion exercise.',                           '11111111-0000-0000-0000-000000000009', E'1. Lie on back with knees bent.\n2. Curl shoulders toward knees.\n3. Lower under control.'),
    ('22222222-0000-0000-0000-000000000024', 'Russian Twist',        'Rotational core exercise targeting obliques.',                 '11111111-0000-0000-0000-000000000009', E'1. Sit with knees bent, lean back slightly.\n2. Rotate torso left and right.\n3. Add weight for increased difficulty.'),
    ('22222222-0000-0000-0000-000000000025', 'Treadmill Run',        'Cardiovascular running on a treadmill.',                      '11111111-0000-0000-0000-000000000010', E'1. Set speed and incline.\n2. Run for target duration or distance.\n3. Cool down with a 5-minute walk.'),
    ('22222222-0000-0000-0000-000000000026', 'Rowing Machine',       'Full-body cardio exercise on a rowing ergometer.',            '11111111-0000-0000-0000-000000000010', E'1. Sit on the seat, feet strapped in.\n2. Drive with legs, lean back, pull handle to chest.\n3. Reverse sequence to return.'),
    ('22222222-0000-0000-0000-000000000027', 'Cycling',              'Stationary bike cardiovascular exercise.',                    '11111111-0000-0000-0000-000000000010', E'1. Adjust seat height.\n2. Pedal at target cadence and resistance.\n3. Cool down at lower resistance.');
